class CustomParserInfo(parserinfo):

    def validate(self, res):
        if res.year and res.year < 1900:
            return False
        return super().validate(res)

class CustomParserInfo(parserinfo):

    def pertain(self, name):
        if name == 'quarter':
            return ['q1', 'q2', 'q3', 'q4']
        return super().pertain(name)
